import pytest
from candidate import monotonic

def test_monotonic_increasing():
    assert monotonic([1, 2, 3, 4]) == True

def test_monotonic_decreasing():
    assert monotonic([4, 3, 2, 1]) == True

def test_monotonic_non_increasing():
    assert monotonic([1, 2, 1, 0]) == True

def test_monotonic_non_increasing_non_monotonic():
    assert monotonic([1, 3, 2, 4]) == False

def test_monotonic_empty_list():
    assert monotonic([]) == True

def test_monotonic_none():
    with pytest.raises(TypeError):
        monotonic(None)

def test_monotonic_single_element_list():
    assert monotonic([1]) == True

def test_monotonic_mixed_types():
    with pytest.raises(TypeError):
        monotonic([1, 'a', 3])

def test_monotonic_large_number():
    assert monotonic([1000000, 1000000, 1000000]) == True

def test_monotonic_large_different_number():
    assert monotonic([1000000, 1000001, 1000002]) == True

def test_monotonic_large_different_number_non_monotonic():
    assert monotonic([1000000, 999999, 1000002]) == False

def test_monotonic_large_decreasing():
    assert monotonic([1000000, 999999, 999998]) == True

def test_monotonic_large_increasing():
    with pytest.raises(TypeError):
        monotonic([1, 2, 'a', 4])
